		//
		//铲掉植物
		//
		function removePlant() {
			var plantRow = Math.floor((trueMouseY - borderTop) / gridHeight);
			var plantCol = Math.floor((trueMouseX - borderLeft) / gridWidth);
		
			movingShovel.removeEventListener("click", removePlant); // removes the CLICK listener from the draggable plant
			overlayContainer.removeChild(shovelSelector); // removes the selector
			overlayContainer.removeChild(movingShovel); // removes the plant itself
		
			// 判断鼠标是否在放置区域内部并且上面没有植物
			if (plantRow >= 0 && plantCol >= 0 && plantRow < 5 && plantCol < 9 && plantsArray[plantRow][plantCol] != 0) {
				var ShoveledPlant;
				if (plantsArray[plantRow][plantCol] == 1) {
					ShoveledPlant = plantContainer.getChildByName("plant_" + plantRow + "_" + plantCol);
					plantContainer.removeChild(ShoveledPlant);
				} else {
					ShoveledPlant = SunFlowerContainer.getChildByName("plant_SunFlower_" + plantRow + "_" + plantCol);
					SunFlowerContainer.removeChild(ShoveledPlant);
				}
				plantsArray[plantRow][plantCol] = 0; // 更新游戏区块信息
			}
			isShoveling = false; // tells the script the player is no longer moving
			card_shovel.visible = true;
		}
		//
		// core function to be executed at every frame. The whole game is managed here
		//
		function onEnterFrm() {
			var i;
			var j;
			var k; //这些变量都是用来遍历的
		
			//若被按下暂停键
			if (stopGame) {
				StopAllFilms();
				StopAllTimers();
		
				return;
			}
		
			trueMouseX = stage.mouseX / stage.scaleX;
			trueMouseY = stage.mouseY / stage.scaleY;
		
			//
			// 遍历豌豆射手，判断是否需要射击
			//
			for (i = 0; i < plantContainer.numChildren; i++) {
				//遍历每个植物
				currentPlant = plantContainer.getChildAt(i);
				currentPlant.play();
				// 准备好开火
				if (currentPlant.recharge == currentPlant.fireRate) {
					// 检查是否有僵尸与植物处于同一行
					if (zombiesArray[currentPlant.plantRow].length > 0) {
						// 同行有僵尸
						for (j = 0; j < zombiesArray[currentPlant.plantRow].length; j++) { //遍历当前行的僵尸
							var targetZombie = zombieContainer.getChildByName(zombiesArray[currentPlant.plantRow][j]); // 获取第j个僵尸
							// 僵尸在右
							if (targetZombie.x > currentPlant.x) {
								var bullet = new lib.bulletMc(); // 构造新子弹
								bulletContainer.addChild(bullet); // 添加子弹
								bullet.x = currentPlant.x + 80;
								bullet.y = currentPlant.y + 30;
								bullet.sonOf = currentPlant; //子弹当儿子，存储该子弹是由哪一株植物射出的
								currentPlant.recharge = 0; // 重新装填
								break; // exits the j for loop
							}
						}
					}
				}
				// 子弹装填中
				if (currentPlant.recharge < currentPlant.fireRate) {
					currentPlant.recharge++; // recharges the plant
				}
			}
		
			//
			// 遍历子弹
			//
			for (i = 0; i < bulletContainer.numChildren; i++) {
				var movingBullet = bulletContainer.getChildAt(i);
				movingBullet.x += bulletSpeed; //子弹移动
				var firingPlant = movingBullet.sonOf; //获得这个子弹是哪个植物射击的
				// 子弹飞行，遍历僵尸，看哪只会与子弹相遇
				for (j = 0; j < zombieContainer.numChildren; j++) {
					movingZombie = zombieContainer.getChildAt(j);
					//var movingZombie=zombieContainer.getChildAt(j);
					//对于当前子弹，遍历的这只僵尸如果不在同一行，就继续找下一只僵尸
					if (movingZombie.zombieRow != firingPlant.plantRow) continue;
					// 在同一行，检测是否碰撞
					if (movingBullet.x > movingZombie.x - 10 && movingBullet.x < movingZombie.x + 10) {
						movingZombie.blood -= 2;
						bulletContainer.removeChild(movingBullet); // 移除这颗子弹
					}
				}
				if (movingBullet.x > 960) {
					bulletContainer.removeChild(movingBullet); // 移除这颗子弹
				}
			}
		
			//
			// 遍历僵尸，判断它的状态
			//
			var zombieColumn;
			for (i = 0; i < zombieContainer.numChildren; i++) //遍历僵尸 
			{
				movingZombie = zombieContainer.getChildAt(i); //得到僵尸
				movingZombie.play();
				zombieColumn = Math.floor((movingZombie.x - borderLeft) / gridWidth); // 得到僵尸所在的列
		
				//先判断是否死亡
				if (movingZombie.blood <= 0) {
					movingZombie.isDead = true;
					movingZombie.isAttacking = false;
					movingZombie.isWalking = false;
				}
				//如果没死亡，并且格子里没有植物，僵尸前进
				else if (zombieColumn < 0 || zombieColumn > 8 || plantsArray[movingZombie.zombieRow][zombieColumn] == 0) {
					movingZombie.isWalking = true;
					movingZombie.isDead = false;
					movingZombie.isAttacking = false;
					movingZombie.x -= speed;
				}
				//没死亡，碰到植物
				else {
					movingZombie.isAttacking = true;
					movingZombie.isWalking = false;
					movingZombie.isDead = false;
					var attackedPlant;
					if (plantsArray[movingZombie.zombieRow][zombieColumn] == 1)
						attackedPlant = plantContainer.getChildByName("plant_" + movingZombie.zombieRow + "_" + zombieColumn);
					else
						attackedPlant = SunFlowerContainer.getChildByName("plant_SunFlower_" + movingZombie.zombieRow + "_" + zombieColumn);
		
		
					//植物受到攻击闪烁
					attackedPlant.alpha = 1 - AlphaTimer1 * Alpha_AP;
					AlphaTimer2 += 1;
					if (AlphaTimer2 >= 24) //每秒闪烁一次
					{
						AlphaTimer1 = 1 - AlphaTimer1;
						AlphaTimer2 = 0;
					}
		
					attackedPlant.hp -= 0.01; // 植物逐渐死亡
					attackedPlant.plantCol = zombieColumn;
		
					// 植物死了
					if (attackedPlant.hp <= 0) {
						//重置透明度计时器
						attackedPlant.alpha = 1;
						AlphaTimer1 = 0;
						AlphaTimer2 = 0;
		
						//植物被吃光僵尸未死，僵尸立刻恢复行走
						movingZombie.gotoAndPlay(0);
						movingZombie.isAttacking = false;
						movingZombie.isWalking = true;
						movingZombie.isDead = false;
		
						//移除植物
						if (plantsArray[movingZombie.zombieRow][zombieColumn] == 1)
							plantContainer.removeChild(attackedPlant);
						else
							SunFlowerContainer.removeChild(attackedPlant);
						plantsArray[attackedPlant.plantRow][attackedPlant.plantCol] = 0; //removes the plant from the array
					}
		
				}
		
				//僵尸正常行走
				if (movingZombie.isWalking && movingZombie.currentFrame == 77) {
					movingZombie.gotoAndPlay(0);
				}
				//僵尸攻击
				if (movingZombie.isAttacking && (movingZombie.currentFrame == 173 || movingZombie.currentFrame < 110)) {
					movingZombie.gotoAndPlay(110);
				}
				//僵尸死亡
				if (movingZombie.isDead && (movingZombie.currentFrame < 78 || movingZombie.currentFrame > 109)) {
					movingZombie.gotoAndPlay(78);
				}
				//判断死亡移除
				if (movingZombie.currentFrame == 109) {
					zombiesArray[movingZombie.zombieRow].splice(zombiesArray[movingZombie.zombieRow].indexOf(movingZombie.name), 1);
					zombieContainer.removeChild(movingZombie); // 移除显示列表
				}
		
				//僵尸走出草坪：游戏失败，暂停画面，5s后转跳第一帧初始页面
				if (movingZombie.x <= borderLeft && movingZombie.x >= borderLeft - 50) {
		
					StopGame = true;
					StopMoving();
					ZW();
					//gotoAndStop(0);
				}
		
			}
		
			//
			// 遍历阳光
			//
			for (i = 0; i < sunContainer.numChildren; i++) {
				fallingSun = sunContainer.getChildAt(i);
				fallingSun.play();
				// 阳光下落
				if (fallingSun.y < fallingSun.destinationY) {
					fallingSun.y++; // 接着下落
				} else {
					fallingSun.alpha -= 0.01; // 落完逐渐消失
					// 阳光消失了
					if (fallingSun.alpha < 0) {
						fallingSun.removeEventListener("click", sunClicked);
						sunContainer.removeChild(fallingSun); // removes the sun
						//console.log("下面展现的是消失的太阳");
						//console.log(fallingSun);
					}
				}
			}
		
			// 阳光收集动画
			for (i = 0; i < sun_ClickContainer.numChildren; i++) {
		
				var sun_click = sun_ClickContainer.getChildAt(i);
		
				//阳光移动到（5，20）
				if (sun_click.x >= 5 || sun_click.y >= 20) {
					sun_click.x -= 4;
					var k_sun = (sun_click.y / sun_click.x) * 4; //4是阳光目标距原点斜率
					sun_click.y -= k_sun;
				}
				if (sun_click.x <= 5 || sun_click.y <= 20) {
					sun_ClickContainer.removeChild(sun_click);
				}
			}
		
			//
			// 遍历太阳花，判断是否生产阳光
			//
			for (i = 0; i < SunFlowerContainer.numChildren; i++) {
				//遍历每个植物
				currentSunFlower = SunFlowerContainer.getChildAt(i);
				currentSunFlower.play();
				// 准备好生产
				if (currentSunFlower.recharge == currentSunFlower.proRate) {
					var sunFromFlower = new lib.sunMc(); // 构造新阳光
					sunContainer.addChild(sunFromFlower); // 添加阳光
					sunFromFlower.x = currentSunFlower.x + 50;
					sunFromFlower.y = currentSunFlower.y + 50;
					sunFromFlower.destinationY = currentSunFlower.y;
					sunFromFlower.alpha = 1;
					sunFromFlower.mouseChildren = false;
					sunFromFlower.addEventListener("click", sunClicked); // 给阳光注册点击事件
					currentSunFlower.recharge = 0; // 重新装填
				}
				// 生产装填中
				if (currentSunFlower.recharge < currentSunFlower.proRate) {
					currentSunFlower.recharge++; // recharges the plant
				}
			}
		
		
		
		
			//
			// 豌豆射手被拿起
			//
			if (playerMoving) {
				movingPlant.x = trueMouseX;
				movingPlant.y = trueMouseY;
				//console.log("trueMouseX = " + trueMouseX);
				//console.log("trueMouseY = " + trueMouseY);
				var plantRow = Math.floor((trueMouseY - borderTop) / gridHeight);
				var plantCol = Math.floor((trueMouseX - borderLeft) / gridWidth);
				// 鼠标在区域内
				if (plantRow >= 0 && plantCol >= 0 && plantRow < 5 && plantCol < 9) {
					selector.visible = true; // shows the selector
					selector.x = movingPlant.x - 40;
					selector.y = movingPlant.y + 30;
				} else {
					selector.visible = false; // hide the selector
				}
			}
		
			//
			// 太阳花被拿起
			//
			if (playerMoving_sunflower) {
				movingSunFlower.x = trueMouseX;
				movingSunFlower.y = trueMouseY;
				//console.log("mouseY:"+trueMouseX);
				//console.log("mouseY:"+trueMouseY);
				var plantRow_2 = Math.floor((trueMouseY - borderTop) / gridHeight);
				var plantCol_2 = Math.floor((trueMouseX - borderLeft) / gridWidth);
				//console.log("plantRow:"+plantRow);
				//console.log("plantCol:"+plantCol);
				// 鼠标在区域内
				if (plantRow_2 >= 0 && plantCol_2 >= 0 && plantRow_2 < 5 && plantCol_2 < 9) {
					selector.visible = true; // shows the selector
					selector.x = movingSunFlower.x - 40;
					selector.y = movingSunFlower.y + 30;
				} else {
					selector.visible = false; // hide the selector
				}
				//console.log("selector.x:"+selector.x);
				//console.log("selector.y:"+selector.y);
			}
		
			//
			//铲子被拿起
			//
			if (isShoveling) {
				movingShovel.x = trueMouseX;
				movingShovel.y = trueMouseY;
				//overlayContainer.addChild(movingShovel);
				var ShovelRow = Math.floor((trueMouseX - borderTop) / gridHeight);
				var ShovelCol = Math.floor((trueMouseY - borderLeft) / gridWidth);
				console.log("ShovelRow:" + ShovelRow);
				console.log("ShovelCol:" + ShovelCol);
				// 鼠标在区域内
				if (ShovelRow >= 0 && ShovelCol >= 0 && ShovelRow < 5 && ShovelCol < 9 && plantsArray[ShovelRow][ShovelCol] != 0) {
		
					shovelSelector.visible = true; // shows the selector
					shovelSelector.x = movingShovel.x;
					shovelSelector.y = movingShovel.y + gridHeight / 10;
				} else {
					shovelSelector.visible = false; // hide the selector
				}
		
			}
		}
		
